import Foundation
import AppKit
import SwiftUI

/// Central provider and renderer for the official "i search" branding assets and icons.
@MainActor
public enum AppBranding {
    private static var cachedMenuBarIcon: NSImage?
    private static var cachedAppIcon: NSImage?
    private static var cachedLogo: NSImage?

    /// Returns the official monochrome menu bar icon (18x18 pt) matching native macOS menu bar appearance.
    public static func menuBarIcon() -> NSImage {
        if let cached = cachedMenuBarIcon {
            return cached
        }

        let image = NSImage(size: NSSize(width: 18, height: 18))

        // Add 2x Retina representation (36x36 px)
        if let data2x = loadData(named: "menubar_template@2x"),
           let rep2x = NSBitmapImageRep(data: data2x) {
            rep2x.size = NSSize(width: 18, height: 18)
            image.addRepresentation(rep2x)
        }

        // Add 1x standard representation (18x18 px)
        if let data1x = loadData(named: "menubar_template"),
           let rep1x = NSBitmapImageRep(data: data1x) {
            rep1x.size = NSSize(width: 18, height: 18)
            image.addRepresentation(rep1x)
        }

        if image.representations.isEmpty {
            if let fallback = loadImage(named: "menubar_template@2x") ?? loadImage(named: "menubar_template") {
                fallback.size = NSSize(width: 18, height: 18)
                fallback.isTemplate = true
                cachedMenuBarIcon = fallback
                return fallback
            }
        }

        image.isTemplate = true
        cachedMenuBarIcon = image
        return image
    }

    /// Returns the official blue squircle app icon scaled to the specified point size.
    public static func appIcon(size: CGFloat = 32) -> NSImage {
        if let base = cachedAppIcon ?? loadImage(named: "app_icon") {
            cachedAppIcon = base
            let copy = base.copy() as! NSImage
            copy.size = NSSize(width: size, height: size)
            return copy
        }

        return fallbackIcon(size: size)
    }

    /// Returns the official horizontal logo banner (squircle mark + "i search" wordmark).
    public static func logo(height: CGFloat = 28) -> NSImage {
        if let base = cachedLogo ?? loadImage(named: "logo") {
            cachedLogo = base
            let aspectRatio = base.size.width / max(1, base.size.height)
            let width = height * aspectRatio
            let copy = base.copy() as! NSImage
            copy.size = NSSize(width: width, height: height)
            return copy
        }

        return fallbackLogo(height: height)
    }

    // MARK: - Asset Loader

    private static func loadData(named name: String) -> Data? {
        // 1. Bundle lookup
        if let url = Bundle.main.url(forResource: name, withExtension: "png"),
           let data = try? Data(contentsOf: url) {
            return data
        }

        // 2. Resource directories lookup
        let candidatePaths = [
            "Resources/\(name).png",
            "../Resources/\(name).png"
        ]
        for path in candidatePaths {
            if FileManager.default.fileExists(atPath: path),
               let data = try? Data(contentsOf: URL(fileURLWithPath: path)) {
                return data
            }
        }

        // 3. Embedded base64 fallback
        if let b64 = embeddedBase64(for: name),
           let data = Data(base64Encoded: b64) {
            return data
        }

        return nil
    }

    private static func loadImage(named name: String) -> NSImage? {
        if let data = loadData(named: name) {
            return NSImage(data: data)
        }
        return nil
    }

    private static func embeddedBase64(for name: String) -> String? {
        switch name {
        case "menubar_template@2x":
            return ""
        case "menubar_template":
            return ""
        case "app_icon":
            return ""
        case "logo":
            return ""
        default:
            return nil
        }
    }

    private static func fallbackIcon(size: CGFloat) -> NSImage {
        let img = NSImage(size: NSSize(width: size, height: size))
        img.lockFocus()
        let rect = NSRect(origin: .zero, size: NSSize(width: size, height: size))
        let path = NSBezierPath(roundedRect: rect, xRadius: size * 0.22, yRadius: size * 0.22)
        NSColor(red: 0.09, green: 0.48, blue: 0.97, alpha: 1.0).setFill()
        path.fill()
        img.unlockFocus()
        return img
    }

    private static func fallbackLogo(height: CGFloat) -> NSImage {
        let icon = appIcon(size: height)
        let width = height * 2.8
        let img = NSImage(size: NSSize(width: width, height: height))
        img.lockFocus()
        icon.draw(in: NSRect(x: 0, y: 0, width: height, height: height))
        img.unlockFocus()
        return img
    }
}

/// SwiftUI view displaying the official i search app icon mark.
public struct AppIconView: View {
    public let size: CGFloat

    public init(size: CGFloat = 20) {
        self.size = size
    }

    public var body: some View {
        Image(nsImage: AppBranding.appIcon(size: size))
            .resizable()
            .aspectRatio(contentMode: .fit)
            .frame(width: size, height: size)
    }
}

/// SwiftUI view displaying the full official i search logo banner (mark + wordmark).
public struct AppLogoView: View {
    public let height: CGFloat

    public init(height: CGFloat = 28) {
        self.height = height
    }

    public var body: some View {
        Image(nsImage: AppBranding.logo(height: height))
            .resizable()
            .aspectRatio(contentMode: .fit)
            .frame(height: height)
    }
}
